#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y;
    Point(double x_=0, double y_=0) : x(x_), y(y_) {}
    override string toString() const {
        ostringstream oss;
        oss << "(" << x << "," << y << ")";
        return oss.str();
    }
    Point sub(const Point &other) const {
        return Point(x - other.x, y - other.y);
    }
    Point moveAlongLine(const struct Line &line, double length) const;
    Point moveAlongVector(const Point &vec, double length) const;
    Point add(const Point &other) const {
        return Point(x + other.x, y + other.y);
    }
    Point mul(double f) const {
        return Point(x * f, y * f);
    }
    Point normalize() const {
        double len = sqrt(x * x + y * y);
        return div(len);
    }
    Point div(double f) const {
        return Point(x / f, y / f);
    }
    Point getAlpha() const {
        return Point(-y, x);
    }
    bool equals(const Point &other) const {
        return std::abs(x - other.x) < 1e-10 && std::abs(y - other.y) < 1e-10;
    }
    int compareTo(const Point &o) const {
        if (equals(o)) return 0;
        if (std::abs(x - o.x) < 1e-10) {
            return (y < o.y) ? -1 : 1;
        }
        return (x < o.x) ? -1 : 1;
    }
};

struct Line {
    Point from, to;
    Line(const Point &f, const Point &t) : from(f), to(t) {}
    Point asVector() const {
        return to.sub(from);
    }
    double length() const {
        return hypot(to.x - from.x, to.y - from.y);
    }
};

// Function implementation for Point.moveAlongLine
Point Point::moveAlongLine(const Line &line, double length) const {
    return moveAlongVector(line.asVector(), length);
}

// Function implementation for Point.moveAlongVector
Point Point::moveAlongVector(const Point &vec, double length) const {
    double mag = sqrt(vec.x * vec.x + vec.y * vec.y);
    if (mag < 1e-15) return Point(x, y);
    return add(Point(vec.x / mag, vec.y / mag).mul(length));
}

double distance(const Point &a, const Point &b) {
    return hypot(a.x - b.x, a.y - b.y);
}

struct Circle {
    Point center;
    int r;
    Circle(int x_, int y_, int r_) : center(x_, y_), r(r_) {}
    static bool isIntersect(const Circle &a, const Circle &b) {
        double d = distance(a.center, b.center);
        return d <= a.r + b.r + 1e-10 && d + 1e-10 >= abs(a.r - b.r);
    }
    static bool isIntersect2(const Circle &a, const Circle &b) {
        double d = distance(a.center, b.center);
        return d < a.r + b.r && d > abs(a.r - b.r);
    }
    static void intersectAt(const Circle &a, const Circle &b, set<Point> &set_points) {
        if (!isIntersect(a, b)) {
            return;
        }
        Line line(a.center, b.center);
        double d = distance(a.center, b.center);
        double middleDistance = (d * d - b.r * b.r + a.r * a.r) / (2 * d);
        Point middle = a.center.moveAlongLine(line, middleDistance);
        Point alpha = line.asVector().getAlpha();
        double height = sqrt(a.r * a.r - middleDistance * middleDistance);
        Point first = middle.moveAlongVector(alpha, height);
        Point second = middle.moveAlongVector(alpha, -height);
        set_points.insert(first);
        if (!second.equals(first)) {
            set_points.insert(second);
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Circle> circles;
    circles.reserve(n);
    for (int i = 0; i < n; ++i) {
        int x, y, r;
        cin >> x >> y >> r;
        circles.emplace_back(x, y, r);
    }
    if (n == 3 && !Circle::isIntersect(circles[0], circles[1])) {
        int sum = 4;
        if (Circle::isIntersect2(circles[0], circles[2])) {
            sum++;
        }
        if (Circle::isIntersect2(circles[1], circles[2])) {
            sum++;
        }
        cout << sum << "\n";
        return 0;
    }
    int total = 1;
    set<Point> set_points;
    for (int i = 0; i < n; ++i) {
        set_points.clear();
        total++;
        for (int j = 0; j < i; ++j) {
            Circle::intersectAt(circles[i], circles[j], set_points);
        }
        if (set_points.size() >= 2) {
            total += (int)set_points.size() - 1;
        }
    }
    cout << total << "\n";
    return 0;
}

